<style>
.snatch-hub{max-width:1240px;color:var(--theme-text,#e5e7eb)}
.snatch-overview{background:var(--theme-surface,#17202d);border:1px solid var(--theme-border,#334155);border-radius:16px;margin-bottom:20px;box-shadow:0 6px 20px var(--theme-shadow,rgba(0,0,0,.08));overflow:hidden}
.snatch-heading{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:24px;margin:0}
