.snatch-heading p{color:var(--theme-muted,#94a3b8);margin:0;max-width:700px;font-size:13px;line-height:1.7}
.snatch-count{display:flex;flex-direction:column;align-items:center;min-width:100px;padding:14px 24px;border:1px solid var(--theme-border,#334155);border-radius:16px;background:var(--theme-surface-alt,#202c3d)}
.snatch-count strong{font-size:1.8rem;line-height:1.2}.snatch-count span{font-size:13px;color:var(--theme-muted,#94a3b8)}
