.snatch-tabs a{display:flex;align-items:center;gap:8px;padding:10px 14px;border-radius:9px;text-decoration:none;color:var(--theme-muted,#94a3b8);font-size:.9rem;font-weight:600}
.snatch-tabs a:hover{background:var(--theme-surface-alt,#202c3d);color:var(--theme-text,#e5e7eb)}
.snatch-tabs a.is-current{background:var(--theme-blue-soft,rgba(59,130,246,.15));color:var(--theme-blue-text,#93c5fd)}
.snatch-list-heading{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px 20px;font-size:13px;line-height:1.6;color:var(--theme-text,#e5e7eb);padding:15px 24px;border-top:1px solid var(--theme-border,#334155);background:var(--theme-surface-alt,#202c3d)}
.snatch-list-heading>span{display:flex;align-items:center;gap:8px}.snatch-list-heading i{color:var(--theme-blue-text,#93c5fd);flex-shrink:0}.snatch-summary-target{color:var(--theme-muted,#94a3b8)}
.snatch-list{display:grid;gap:18px}.snatch-entry{border:1px solid var(--theme-border,#334155);border-left:3px solid var(--theme-border,#334155);border-radius:16px;background:var(--theme-surface,#17202d);padding:20px;box-shadow:0 6px 20px var(--theme-shadow,rgba(0,0,0,.08));overflow:hidden}
.snatch-entry-success{border-left-color:var(--theme-green-text,#4ade80)}.snatch-entry-danger{border-left-color:var(--theme-red-text,#f87171)}.snatch-entry-info{border-left-color:var(--theme-blue-text,#93c5fd)}
.snatch-entry-top{display:flex;align-items:flex-start;justify-content:space-between;gap:18px}
.snatch-torrent{display:flex;gap:14px;min-width:0}.snatch-torrent>div:last-child{min-width:0}.snatch-file-icon{display:flex;align-items:center;justify-content:center;flex:0 0 44px;height:48px;border-radius:12px;background:var(--theme-blue-soft,rgba(59,130,246,.12));color:var(--theme-blue-text,#93c5fd);font-size:1.35rem}
.snatch-entry-label{font-size:13px;color:var(--theme-muted,#94a3b8);margin-bottom:5px}.snatch-entry h2{font-size:1.05rem;line-height:1.5;font-weight:650;margin:0;overflow-wrap:anywhere}.snatch-entry h2 a{color:var(--theme-text,#e5e7eb);text-decoration:none}.snatch-entry h2 a:hover{text-decoration:underline}
