.snatch-metrics dt{font-weight:400;font-size:13px;color:var(--theme-muted,#94a3b8);margin-bottom:5px}.snatch-metrics dt i{margin-right:4px}.snatch-metrics dd{font-weight:650;font-size:1.1rem;margin:0 0 4px;overflow-wrap:anywhere}.snatch-metrics small{font-size:13px;color:var(--theme-muted,#94a3b8)}
.snatch-progress-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.snatch-progress-label{display:flex;justify-content:space-between;gap:10px;font-size:13px;margin-bottom:8px;color:var(--theme-muted,#94a3b8)}.snatch-progress-label strong{font-weight:600;color:var(--theme-text,#e5e7eb)}
.snatch-progress{height:6px;border-radius:10px;background:var(--theme-surface-alt,#263448);overflow:hidden}.snatch-progress span{display:block;height:100%;border-radius:10px;background:var(--theme-green-text,#4ade80)}.snatch-progress-download span{background:var(--theme-blue-text,#93c5fd)}
.snatch-guidance{display:flex;align-items:flex-start;gap:9px;margin-top:20px;font-size:13px;color:var(--theme-muted,#94a3b8);line-height:1.6}.snatch-guidance-warning{color:var(--theme-amber-text,#facc15)}.snatch-deadline{display:block;font-size:13px}
.snatch-announce{display:flex;align-items:center;flex-wrap:wrap;gap:6px 10px;margin-top:15px;padding:12px 14px;background:var(--theme-surface-alt,#202c3d);border-radius:10px;font-size:13px}.snatch-announce>i{color:var(--theme-blue-text,#93c5fd)}.snatch-muted{color:var(--theme-muted,#94a3b8)}.snatch-event{padding:2px 8px;border:1px solid var(--theme-border,#334155);border-radius:6px;font-size:13px}
.snatch-actions{display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin-top:18px;padding-top:16px;border-top:1px solid var(--theme-border,#334155)}.snatch-actions form{margin:0!important}.snatch-actions .btn{font-size:13px;border-radius:8px;padding:8px 12px}
.snatch-empty{text-align:center;padding:60px 24px;border:1px dashed var(--theme-border,#334155);border-radius:16px;background:var(--theme-surface,#17202d)}.snatch-empty>i{font-size:2rem;color:var(--theme-muted,#94a3b8)}.snatch-empty h2{font-size:1.15rem;margin:16px 0 8px}.snatch-empty p{color:var(--theme-muted,#94a3b8);font-size:.9rem;margin:0}.snatch-pagination{display:flex;justify-content:center;margin-top:28px}
