@media(max-width:767px){.snatch-entry{padding:18px}.snatch-metrics{grid-template-columns:1fr 1fr}.snatch-progress-grid{grid-template-columns:1fr;gap:16px}.snatch-entry-top{flex-wrap:wrap}.snatch-entry-controls{margin-left:58px}.snatch-count{min-width:76px;padding:12px}.snatch-tabs a{padding:9px 10px;font-size:13px}.snatch-heading{gap:14px;padding:18px;align-items:flex-start}.snatch-heading>div:first-child{min-width:0;overflow-wrap:anywhere}.snatch-list-heading{padding:14px 18px;flex-direction:column;align-items:flex-start}.snatch-announce{align-items:flex-start}}
