.snatch-search{display:flex;align-items:flex-end;flex-wrap:wrap;gap:12px;padding:18px 20px;margin-bottom:20px;border:1px solid var(--theme-border,#334155);border-radius:14px;background:var(--theme-surface,#17202d);font-size:13px}
.snatch-search-field{flex:1 1 260px}.snatch-search label{display:block;font-weight:600;margin-bottom:8px}.snatch-search .form-control{font-size:13px;background:var(--theme-surface-alt,#202c3d);color:var(--theme-text,#e5e7eb);border-color:var(--theme-border,#334155)}.snatch-search .form-control::placeholder{color:var(--theme-muted,#94a3b8)}.snatch-search .btn{font-size:13px}.snatch-search p{flex-basis:100%;margin:0;line-height:1.6;color:var(--theme-muted,#94a3b8)}
.snatch-entry-controls{display:flex;align-items:center;justify-content:flex-end;flex-wrap:wrap;gap:8px;flex-shrink:0}.snatch-delete-form{margin:0}.snatch-delete-form .btn{font-size:13px;padding:6px 10px;border-radius:8px;white-space:nowrap}.snatch-owner{display:inline-flex;align-items:center;gap:6px;padding:6px 11px;border-radius:20px;font-size:13px;background:var(--theme-blue-soft,rgba(59,130,246,.12));color:var(--theme-blue-text,#93c5fd)}
